WITH filtered_departments AS (SELECT *, COALESCE(budget, 0) AS budget_filled FROM departments WHERE budget > 3111000), budget_filled_bucket_summary AS (SELECT CASE WHEN budget_filled >= 71 THEN 'high' WHEN budget_filled >= 33 THEN 'mid' ELSE 'low' END AS budget_filled_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(dept_name))) AS dept_name_values FROM filtered_departments GROUP BY CASE WHEN budget_filled >= 71 THEN 'high' WHEN budget_filled >= 33 THEN 'mid' ELSE 'low' END) SELECT * FROM budget_filled_bucket_summary ORDER BY dept_name_values ASC;
